create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique, display_name text not null default '', avatar_url text, bio text not null default '', interests text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.posts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, content text not null default '', media_url text, media_type text check(media_type in ('image','video')), interest text not null default '일상', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(length(content)<=5000), check(content<>'' or media_url is not null));
create index if not exists posts_created_at_idx on public.posts(created_at desc);
create index if not exists posts_interest_created_idx on public.posts(interest,created_at desc);
create table if not exists public.comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, content text not null check(length(content) between 1 and 2000), created_at timestamptz not null default now());
create index if not exists comments_post_created_idx on public.comments(post_id,created_at);
create table if not exists public.likes (post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(post_id,user_id));
create table if not exists public.follows (follower_id uuid not null references public.profiles(id) on delete cascade, followed_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(follower_id,followed_id), check(follower_id<>followed_id));
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles(id) on delete cascade, actor_id uuid references public.profiles(id) on delete set null, kind text not null check(kind in ('like','comment','follow')), post_id uuid references public.posts(id) on delete cascade, read_at timestamptz, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.posts enable row level security; alter table public.comments enable row level security; alter table public.likes enable row level security; alter table public.follows enable row level security; alter table public.notifications enable row level security;
create policy "profiles are readable" on public.profiles for select using(true);
create policy "users update own profile" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy "posts readable" on public.posts for select using(true);
create policy "users create own posts" on public.posts for insert with check(auth.uid()=user_id);
create policy "users edit own posts" on public.posts for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "users delete own posts" on public.posts for delete using(auth.uid()=user_id);
create policy "comments readable" on public.comments for select using(true);
create policy "users create own comments" on public.comments for insert with check(auth.uid()=user_id);
create policy "users delete own comments" on public.comments for delete using(auth.uid()=user_id);
create policy "likes readable" on public.likes for select using(true);
create policy "users like as self" on public.likes for insert with check(auth.uid()=user_id);
create policy "users unlike as self" on public.likes for delete using(auth.uid()=user_id);
create policy "follows readable" on public.follows for select using(true);
create policy "users follow as self" on public.follows for insert with check(auth.uid()=follower_id);
create policy "users unfollow as self" on public.follows for delete using(auth.uid()=follower_id);
create policy "users read own notifications" on public.notifications for select using(auth.uid()=recipient_id);
create policy "users update own notifications" on public.notifications for update using(auth.uid()=recipient_id) with check(auth.uid()=recipient_id);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('post-media','post-media',false,52428800,array['image/jpeg','image/png','image/webp','image/heic','video/mp4','video/quicktime','video/webm']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "authenticated users read post media" on storage.objects for select to authenticated using(bucket_id='post-media');
create policy "users upload own post media" on storage.objects for insert to authenticated with check(bucket_id='post-media' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "users update own post media" on storage.objects for update to authenticated using(bucket_id='post-media' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='post-media' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "users delete own post media" on storage.objects for delete to authenticated using(bucket_id='post-media' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'username','user_'||left(new.id::text,8)),coalesce(new.raw_user_meta_data->>'display_name',''),new.raw_user_meta_data->>'avatar_url') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
